'use strict';
const V5={weatherPlace:'罗湖',weatherTab:'now',queryTab:'query',feedbackTab:'progress',place:'',profile:stored('sy-v5-profile'),addresses:stored('sy-v5-addresses'),round:false,stay:60,purpose:'日常出行',returnAt:'',timeline:null};
if(Array.isArray(V5.profile))V5.profile={name:'游客',account:'本地体验',language:'中文'};
V2NAV.splice(0,V2NAV.length,['dashboard','出行看板','route'],['map','地点风险','map'],['query','快捷查询','search'],['feedback','用户反馈','message'],['personal','个人中心','layers'],['community','互助与捐赠','message'],['about','关于与设置','layers'],['events','事件追踪与复盘','rain']);
const v5Base={weather:vWeather,form:vForm,dashboard:vDashboard,query:vQueryPage,feedback:vFeedbackPage,about:vAbout,events:vEventsPage,plan:vPlanCard,advice:vRecommendation,commit:vCommitPlan,restore:vRestore};
function v5Stamp(data){return `<div class="v5stamp">资料更新：${esc(data||'参见各条来源的发布时间')} · 页面生成：${esc(dateText(new Date().toISOString()))}</div>`}
function v5End(name){return `${v5Stamp()}<div class="v5export"><span>保留查询时间、依据与未知项</span><button data-v5="report" data-value="${esc(name)}">生成本模块报告 ↗</button></div>`}
function v5Trend(){const w=V2.weather;if(!w?.hourly||V2.mode==='history')return '<div class="empty">查询天气后展示逐小时模型趋势。历史看板不会使用事后天气冒充当时预报。</div>';const h=w.hourly,start=Math.max(0,h.time.findIndex(t=>t>=(w.current?.time||''))),points=h.time.slice(start,start+24);if(!points.length)return '<div class="empty">没有对应时段。</div>';const rain=h.precipitation.slice(start,start+24),temp=h.temperature_2m.slice(start,start+24),max=Math.max(1,...rain),lo=Math.min(...temp),hi=Math.max(lo+1,...temp);return `<div class="v5chart"><div class="row"><b>未来24小时 · ${esc(w.place)}</b><span>蓝柱：小时降水 · 青线：气温</span></div><svg viewBox="0 0 760 230" role="img" aria-label="小时降水和气温趋势"><path d="M40 20V190H735" fill="none" stroke="#b6c7de"/>${points.map((t,i)=>`<rect x="${45+i*28}" y="${190-rain[i]/max*145}" width="15" height="${rain[i]/max*145}" rx="3" fill="#4d82ed"><title>${esc(t)}：${rain[i]}mm，${temp[i]}°C</title></rect>${i%4===0?`<text x="${42+i*28}" y="211" font-size="12" fill="#64748b">${t.slice(11,16)}</text>`:''}`).join('')}<polyline points="${temp.map((t,i)=>(52+i*28)+','+(170-(t-lo)/(hi-lo)*120)).join(' ')}" fill="none" stroke="#159b8e" stroke-width="3"/><text x="40" y="16" font-size="12" fill="#64748b">降水最高 ${max===1&&Math.max(...rain)===0?0:Math.max(...rain)} mm/h · 气温 ${lo}–${hi}°C</text></svg><details><summary>查看趋势数据表</summary><div class="tablewrap"><table><tr><th>时间</th><th>气温°C</th><th>小时降水mm</th><th>降水概率%</th></tr>${points.map((t,i)=>`<tr><td>${esc(t)}</td><td>${temp[i]}</td><td>${rain[i]}</td><td>${h.precipitation_probability?.[start+i]??'未知'}</td></tr>`).join('')}</table></div></details></div>`}
vWeather=function(){return `<div class="v5weatherplace"><label>天气地点 <input id="v5-weather-place" value="${esc(V5.weatherPlace)}" list="v5-weather-places" placeholder="站点或纬度,经度"></label><datalist id="v5-weather-places">${D.stations.map(s=>`<option value="${s.name}">`).join('')}</datalist><button data-v5="weather">查询地点天气</button></div><div class="seg">${[['now','现在'],['planned','计划时段'],['trend','趋势']].map(([a,t])=>`<button data-v5="weather-tab" data-value="${a}" class="${V5.weatherTab===a?'active':''}">${t}</button>`).join('')}</div>${V5.weatherTab==='trend'?v5Trend():v5Base.weather()}<details class="v5special"><summary>台风与特殊天气资料</summary><p>实时台风位置、强度与预测路径待接入，不使用历史路径充当当前事件。</p><a href="https://weather.sz.gov.cn/" target="_blank" rel="noopener">深圳气象官方资料 ↗</a></details>${v5Stamp(V2.weather?.fetchedAt||V2.weather?.current?.time)}${v5End('天气趋势')}`};
vFetchWeather=async function(){if(V2.mode==='history')return toast('历史天气需在复盘查看');vDraft();const el=document.getElementById('v5-weather-place');if(el)V5.weatherPlace=el.value;const place=V5.weatherPlace,weatherSeq=V2.requestSeq,s=vResolve(place);if(!s)return toast('地址坐标未匹配，可输入纬度,经度');try{const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${s.lat}&longitude=${s.lon}&current=temperature_2m,precipitation,wind_speed_10m&hourly=temperature_2m,precipitation,precipitation_probability,weather_code&timezone=Asia%2FShanghai&wind_speed_unit=ms`,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const w=await r.json();if(!w.current||!w.hourly)throw Error();if(V2.mode==='history'||V5.weatherPlace!==place||V2.requestSeq!==weatherSeq)return;V2.weather={...w,place:s.name,fetchedAt:new Date().toISOString()};vRender()}catch{if(V2.mode==='history'||V5.weatherPlace!==place||V2.requestSeq!==weatherSeq)return;V2.weather=null;toast('天气查询未成功，请稍后刷新');vRender()}};
vForm=function(){return v5Base.form().replace('</form>',`<div class="v5shortcuts"><b>我的快捷地址</b>${V5.addresses.map((a,i)=>`<button type="button" data-v5="address" data-value="${i}">${esc(a.label)} · ${esc(a.address)}</button>`).join('')}<button type="button" data-v5="add-address">＋设置家／公司／学校</button></div><div class="v5round"><label><input id="v5-round" type="checkbox" ${V5.round?'checked':''}> 此次需要返回</label><label>出行目的 <select id="v5-purpose">${['日常出行','就医','上班','上学','其他'].map(t=>`<option ${V5.purpose===t?'selected':''}>${t}</option>`).join('')}</select></label>${V5.round?`<label>预计停留 <input id="v5-stay" type="number" min="0" max="1440" value="${V5.stay}"> 分钟</label><label>返程出发时间（可选）<input id="v5-return" type="datetime-local" value="${esc(V5.returnAt)}"></label>`:''}</div></form>`)+v5End('行程设置')};
function v5Risk(p){const stop=vRelated(p).some(e=>/暂停|封闭|停运/.test(e.category)),r=vRisks(p).length,f=vFeedback(p).length;return stop?'公告涉及管制':r?'关联长期隐患':f?'存在待核验线索':'风险未知'}
vPlanCard=function(p,i){return v5Base.plan(p,i).replace('</article>',`<div class="v5risk"><span class="tag orange">${v5Risk(p)}</span><small>危险概率：未取得校准模型</small></div></article>`)};
function v5RoundData(p){const depart=V2.mode==='history'?(p?.at||V2.at):p?.planned|| (V2.departure==='planned'?V2.planned:'')||businessNow().toISOString(),d=new Date(depart.includes('+')||depart.endsWith('Z')?depart:depart+':00+08:00');const duration=p?.duration;const returnTime=V5.returnAt?V5.returnAt:duration!=null?new Date(d.getTime()+(duration+Number(V5.stay)*60)*1000).toISOString():null;return {depart,returnTime}}
function v5RainAt(time){if(!time||!V2.weather?.hourly)return '未取得';const d=new Date(time.includes('+')||time.endsWith('Z')?time:time+':00+08:00');const local=new Date(d.getTime()+8*3600000).toISOString().slice(0,13)+':00',i=V2.weather.hourly.time.indexOf(local);return i>=0?V2.weather.hourly.precipitation[i]+' mm（截至该整点的前1小时累计）':'超出／未匹配预报时段'}
vRecommendation=function(){const p=vFocus(),rt=v5RoundData(p);return v5Base.advice()+`<section class="card v5forecast"><h2>行程风险依据与预测状态</h2><div class="tablewrap"><table><tr><th>时段／对象</th><th>降雨参考</th><th>风险证据</th><th>预测状态</th></tr><tr><td>去程 · ${esc(dateText(rt.depart))}</td><td>${esc(v5RainAt(rt.depart))}</td><td>${v5Risk(p)} · ${vRisks(p).length}条官方关联</td><td>路段风险AI未接入</td></tr>${V5.round?`<tr><td>返程 · ${rt.returnTime?esc(dateText(rt.returnTime)):'时长未取得，请指定返程时刻'}</td><td>${esc(v5RainAt(rt.returnTime))}</td><td>返程路径尚未查询，不能沿用去程风险</td><td>返程风险未知</td></tr>`:''}</table></div><p>${V5.round?'建议分别核对去程、停留期间和返程信息；小时降雨变化仅供参考，不足以判断哪一个时段更安全。':'设置“此次需要返回”，可联动停留时间与返程天气。'}</p>${V5.round?'<button data-v5="return-plan">反向行程，查询返程方案</button>':''}<small>当前为规则关联与天气数据展示；没有训练、校准和验证的模型，不生成危险百分比。</small>${v5End('风险与往返分析')}</section>`};
vCommitPlan=function(p){p.roundTrip={enabled:V5.round,stay:V5.stay,purpose:V5.purpose,returnAt:V5.returnAt};v5Base.commit(p)};
vRestore=function(p,c=false){if(p?.roundTrip&&!c){Object.assign(V5,{round:p.roundTrip.enabled,stay:p.roundTrip.stay,purpose:p.roundTrip.purpose,returnAt:p.roundTrip.returnAt})}v5Base.restore(p,c)};
function v5Sources(){const refs=[...vAvailable().map(r=>({title:r.street+' '+r.guide_year+'指引',url:r.source_url,time:D.guide_dates[r.guide_year]||'发布日期待核实'})),...vRelated(vFocus()).map(e=>({title:e.category+' '+e.place_text,url:e.source_url,time:e.source_published_at}))];const unique=[...new Map(refs.map(r=>[r.url,r])).values()];return `<section class="card v5sources"><h2>数据来源与适用范围</h2>${unique.map(r=>`<div class="listitem"><a target="_blank" rel="noopener" href="${esc(r.url)}">${esc(r.title)} ↗</a><small> · 发布 ${esc(r.time)}</small></div>`).join('')}<p><a href="https://weather.sz.gov.cn/" target="_blank" rel="noopener">深圳气象官方发布</a> · <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo模型天气</a> · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OSM坐标与许可</a> · <a href="https://project-osrm.org/" target="_blank" rel="noopener">OSRM驾车参考</a></p><small>资料收集2026-10-11；静态隐患不代表当前积水，路线不包含实时洪涝。</small>${v5End('数据来源')}</section>`}
vDashboard=function(){return v5Base.dashboard()+v5Sources()};
vQueryPage=function(){return `<div class="seg"><button data-v5="query-tab" data-value="query" class="${V5.queryTab==='query'?'active':''}">查询</button><button data-v5="query-tab" data-value="records" class="${V5.queryTab==='records'?'active':''}">查询记录</button></div>${V5.queryTab==='records'?vHistoryPage().replaceAll('选择导出','生成报告'):v5Base.query()}${v5End('快捷查询')}`};
vMapPage=function(){const names=D.stations;return vHead('PLACE RISKS','地点风险','只查看地点本身与周边资料，不展示出行路线。')+`<section class="card"><h2>地点全图 · 坐标示意</h2>${v5PlaceMap()}<div class="v5placegrid">${names.map(s=>`<button data-v5="place" data-value="${s.name}" class="${V5.place===s.name?'active':''}" style="border-left:4px solid ${vAvailable().some(r=>r.risk_description.includes(s.name+'地铁站'))?'#d38a36':'#829bc1'}">${esc(s.name)}<small>${s.lat.toFixed(3)}, ${s.lon.toFixed(3)}</small></button>`).join('')}</div><small>蓝灰：信息不足；橙色：长期隐患关联。为公开站点分布选择器，完整地理底图待接入。</small><form id="v5-place-form" class="queryform"><input name="place" value="${esc(V5.place)}" placeholder="搜索地点名称"><button>查看地点</button></form></section>${V5.place?v5PlaceDetail(): '<div class="empty">选择地点后查看本身与周边资料。</div>'}${v5End('地点风险')}`};
function v5PlaceDetail(){const p={origin:V5.place,destination:V5.place,vias:[]},s=vResolve(V5.place),near=s?D.stations.filter(x=>x.name!==s.name&&Math.hypot((x.lon-s.lon)*Math.cos(s.lat*Math.PI/180),x.lat-s.lat)*111<1.5):[];return `<section class="card"><h2>${esc(V5.place)} · 本身与周边</h2><p>本身：${v5Risk(p)}；当前水深与可通行状态未知。</p>${vRisks(p).map(r=>`<div class="listitem">${esc(r.risk_description)} ${vSource(r)}</div>`).join('')}<h3>周边约1.5公里公开站点</h3>${near.map(n=>`<button data-v5="place" data-value="${esc(n.name)}">${esc(n.name)}</button>`).join('')||'未取得周边定位数据'}<p>周边状态不能视为地点本身状态，营业和拥挤信息未接入。</p></section>`}
vFeedbackPage=function(){const f=stored('sy-v2-feedback');return v5Base.feedback().split('<section class="card"><h2>我的反馈与处理进度</h2>')[0]+'</div>'+`<section class="card" style="margin-top:20px"><div class="seg"><button data-v5="feedback-tab" data-value="progress">处理进度</button><button data-v5="feedback-tab" data-value="records">反馈记录</button></div>${f.length?f.slice().reverse().map(x=>`<div class="listitem"><button class="linkbutton" data-v5="feedback-detail" data-value="${x.id}">${esc(x.place)} · ${esc(x.status||'待核验')}</button>${V5.feedbackTab==='progress'?v3FeedbackProgress(x):'<p>点击查看原始内容、图片、回复和处理时间。</p>'}</div>`).join(''):'<div class="empty">暂无实际反馈记录</div>'}${v5End('用户反馈')}</section>`};
function v5Personal(){return vHead('YOUR SPACE','个人中心','资料和快捷地址保存在本浏览器；游客与用户内容相同。')+`<div class="panelgrid"><section class="card"><div class="v5avatar">${esc(V5.profile.name.slice(0,1))}</div><h2>${esc(V5.profile.name)}</h2><p>身份：用户游客 · 账号：${esc(V5.profile.account)}</p><form id="v5-profile" class="feedbackform"><label>显示名称<input name="name" value="${esc(V5.profile.name)}" required maxlength="40"></label><label>自定义账号标识<input name="account" value="${esc(V5.profile.account)}" maxlength="80"></label><label>语言偏好<select name="language"><option>中文</option><option ${V5.profile.language==='English'?'selected':''}>English</option></select></label><button class="primary">保存资料</button></form><small>语言偏好可保存，完整英文翻译尚未实现；账号标识不构成登录认证。</small></section><section class="card"><h2>积分与奖励</h2><div class="v5points">0 <small>可兑换积分</small></div><p>积分发放与兑换未接通。维护核验不自动产生积分；待建立有效反馈规则和复核流程。</p><details><summary>拟定奖励规则</summary><p>经核验、有帮助且非重复的反馈可进入奖励审核；积分兑换物资需有真实库存与履约记录。</p></details><h3>快捷地址</h3>${V5.addresses.map((a,i)=>`<div class="row listitem"><span>${esc(a.label)} · ${esc(a.address)}</span><button data-v5="delete-address" data-value="${i}">删除</button></div>`).join('')}<button data-v5="add-address">添加快捷地址</button><h3>帮助与软件反馈</h3><button data-v2="page" data-value="feedback">提交信息错误／使用感受</button></section></div>${v5End('个人中心')}`}
function v5Community(){const rows=stored('sy-v5-help');return vHead('COMMUNITY CARE','互助与捐赠','可保存互助草稿；跨用户发布、接单和支付尚未接通。')+`<div class="panelgrid"><section class="card"><h2>发布互助悬赏 · 本地草稿</h2><form id="v5-help" class="feedbackform"><label>需要的帮助<input name="title" required maxlength="100"></label><label>地点<input name="place" required></label><label>奖励类型<select name="type"><option>积分</option><option>金额（元）</option><option>无偿互助</option></select></label><label>拟定奖励<input name="reward" type="number" min="0" value="0"></label><label class="full">详情<textarea name="detail" required></textarea></label><button class="primary">保存互助草稿</button></form><p>紧急救援需求应通过官方应急渠道求助；草稿不会发送给救援人员。</p></section><section class="card"><h2>我的互助记录</h2>${rows.map(x=>`<div class="listitem"><b>${esc(x.title)}</b><p>${esc(x.place)} · ${esc(x.type)} ${esc(x.reward)}</p><p>${esc(x.detail)}</p><span class="tag gray">${esc(x.status)}</span><button data-v5="help-interest" data-value="${x.id}">标记愿意协助（本地）</button></div>`).join('')||'<div class="empty">没有预填悬赏或接单人数。</div>'}<h2>捐赠渠道与进度</h2><p>尚无已核验受灾募捐项目、收款渠道或进度回执。暂不收款，不显示虚构到账与物资发放进度。</p><small>接入后需列出项目主体、用途、官方渠道、公开进度与更新日期。</small></section></div>${v5End('互助与捐赠')}`}
vAbout=function(){return `<section class="card"><h2>当前账号</h2><p>${esc(V5.profile.name)} · 用户游客 · 本地资料</p><button data-v2="page" data-value="about">编辑个人资料</button></section>`+v5Base.about()+v5End('关于与设置')};
vEventsPage=function(){if(V2.eventTab==='now')return v5Base.events()+`<section class="card"><h2>过往预测与实际 · 验证记录</h2><div class="tablewrap"><table><tr><th>类别</th><th>发布／适用时间</th><th>预测值</th><th>实际观测</th><th>误差／准确率</th><th>偏差解释</th></tr>${['专业机构预测','AI预测'].map(t=>`<tr><td>${t}</td><td>待取得</td><td>未接入</td><td>待专业核验</td><td>无样本，不计算</td><td>待有来源解释</td></tr>`).join('')}</table></div><p>只展示确认正在发生的事件。无实时事件记录时不以历史事件填充；用户报告不作为预测真值。</p>${v5End('当前事件与预测验证')}</section>`;const events=V2.eventId==='sep2023'?D.events.filter(e=>(e.event_start||'2023-09-08').slice(0,10)>=V2.rangeStart&&(e.event_start||'2023-09-08').slice(0,10)<=V2.rangeEnd).sort((a,b)=>(a.event_start||a.available_at).localeCompare(b.event_start||b.available_at)):[];return vHead('EVENT TIMELINE','事件追踪与复盘','事件总览 → 时间线 → 节点详情')+`<div class="seg"><button data-v2="event-tab" data-value="past" class="active">过去事件</button><button data-v2="event-tab" data-value="now">正在发生</button></div><section class="card" style="margin-top:18px"><div class="historyctrl"><select id="v2-recap-event"><option value="sep2023" ${V2.eventId==='sep2023'?'selected':''}>2023年9月深圳暴雨</option><option value="saola2023" ${V2.eventId==='saola2023'?'selected':''}>苏拉（待补资料）</option></select><input id="v2-range-start" type="date" value="${V2.rangeStart}">—<input id="v2-range-end" type="date" value="${V2.rangeEnd}"></div>`+`<div class="v5eventoverview"><div><small>已收录事实</small><b>${events.length} 条</b></div><div><small>灾损统计</small><b>未取得</b></div><div><small>降雨背景</small><b>ERA5事后资料</b></div></div><div class="v5timeline">${events.map(e=>`<button data-v5="timeline" data-value="${e.record_id}" class="${V5.timeline===e.record_id?'active':''}"><small>${esc(e.event_time_text)}</small><b>${esc(e.category)} · ${esc(e.place_text)}</b></button>`).join('')||'<div class="empty">该事件暂无时间线资料</div>'}</div></section><section class="card"><h2>时间线节点详情</h2>${V5.timeline?v5TimelineDetail():'<p>点击节点查看当时记录和原始依据。</p>'}${v5End('事件复盘')}</section>`};
function v5TimelineDetail(){const e=D.events.find(x=>x.record_id===V5.timeline);return e?`<h3>${esc(e.place_text)}</h3><p data-original>${esc(e.summary)}</p><p>事件时间：${esc(e.event_time_text)} · 发布时间：${esc(e.source_published_at)}</p>${vEventSource(e)}${e.event_start?.includes('T')?`<button data-v2="replay" data-value="${e.event_start.slice(0,16)}">查看当时出行信息</button>`:''}`:'未找到记录'}
const v5OldRender=vRender;vRender=function(){if(V3.role==='user'&&['personal','community'].includes(V2.page)){const page=V2.page;V2.page='about';v5OldRender();V2.page=page;const c=document.querySelector('.content');if(c)c.innerHTML=page==='personal'?v5Personal():v5Community();const b=document.querySelector('.breadcrumb');if(b)b.textContent=page==='personal'?'深圳 / 个人中心':'深圳 / 互助与捐赠';document.querySelectorAll('[data-v2="page"]').forEach(x=>x.classList.toggle('active',x.dataset.value===page));return}v5OldRender()};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-v5]');if(!b)return;vDraft();const a=b.dataset.v5,v=b.dataset.value;if(a==='weather')return vFetchWeather();if(a==='weather-tab'){V5.weatherTab=v;if(v==='planned')V2.departure='planned';if(v==='now')V2.departure='immediate'}if(a==='query-tab')V5.queryTab=v;if(a==='feedback-tab')V5.feedbackTab=v;if(a==='place')V5.place=v;if(a==='timeline')V5.timeline=v;if(a==='add-address')return vDialog('设置快捷地址',`<form id="v5-address-form" class="feedbackform"><label>标签<input name="label" placeholder="家／公司／学校" required></label><label>地址<input name="address" placeholder="小区名称或详细地址" required></label><small>可自由保存地址；地图坐标仍需匹配。</small><button class="primary">保存</button></form>`);if(a==='address'){const x=V5.addresses[Number(v)];if(x){V2.origin=x.address;toast('快捷地址已填入出发点')}}if(a==='delete-address'){V5.addresses.splice(Number(v),1);save('sy-v5-addresses',V5.addresses)}if(a==='return-plan'){const rt=v5RoundData(vFocus());[V2.origin,V2.destination]=[V2.destination,V2.origin];V2.vias.reverse();if(rt.returnTime){V2.departure='planned';V2.planned=rt.returnTime.endsWith('Z')?new Date(new Date(rt.returnTime).getTime()+8*3600000).toISOString().slice(0,16):rt.returnTime}V5.round=false;toast('已切换返程，请生成方案核对实际路径')}if(a==='feedback-detail'){const f=stored('sy-v2-feedback').find(x=>x.id===v);if(f)return vDialog('反馈记录与回复',`<h3>${esc(f.place)}</h3><p>${esc(f.content)}</p><p>观察 ${esc(dateText(f.observed))} · 提交 ${esc(dateText(f.submitted))}</p>${vPhoto(f)}${v3FeedbackProgress(f)}`)}if(a==='help-interest'){const rows=stored('sy-v5-help');const x=rows.find(x=>x.id===v);if(x)x.status='本地意向标记 · 未跨用户接单';save('sy-v5-help',rows)}if(a==='report'){V5.reportMarkup=b.closest('section')?.innerHTML||document.querySelector('.content')?.innerHTML||'';return vDialog('生成报告 · '+v,`<p>导出保留当前模块文字、图表、来源与状态。包含个人资料或本地图片时，请自行选择分享对象。</p><button data-v5="download-report" data-value="${esc(v)}">下载HTML报告（浏览器可打印PDF）</button>`)}if(a==='download-report'){const html=(V5.reportMarkup||'').replace(/<button\b([^>]*data-v2="source"[^>]*)>[\s\S]*?<\/button>/g,(_,attrs)=>{const k=attrs.match(/data-kind="([^"]*)"/)?.[1],v=attrs.match(/data-value="([^"]*)"/)?.[1],r=k==='risk'?vAvailable().find(r=>r.street===v):D.events.find(e=>e.record_id===v);return r?'<a href="'+esc(r.source_url)+'">原始依据 ↗</a>':''}).replace(/<form\b[\s\S]*?<\/form>/g,'').replace(/<button\b[\s\S]*?<\/button>/g,'');download('深雨知路_'+v+'.html',`<!doctype html><meta charset="utf-8"><title>${esc(v)}报告</title><style>body{max-width:1000px;margin:30px auto;font:15px/1.8 sans-serif;color:#18334e}svg,img{max-width:100%}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:8px}.v5export,.seg{display:none}@media print{details{display:block}}</style><h1>深雨知路 · ${esc(v)}报告</h1><p>生成：${esc(dateText(new Date().toISOString()))} · ${V2.mode==='history'?'历史截止 '+esc(V2.at):'当前查询快照'}</p><p>行程：${esc(V2.origin)} → ${V2.vias.map(esc).join(" → ")}${V2.vias.length?" → ":""}${esc(V2.destination)} · ${esc(V2.transport)}${V5.round?" · 需要返回，停留"+V5.stay+"分钟":""}</p>${html}<p>未知不代表安全；尚未接通的预测和服务保持待接入。</p>`,'text/html');return}vRender()});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='v5-round'){V5.round=t.checked;vDraft();vRender()}if(t.id==='v5-stay')V5.stay=Math.max(0,Math.min(1440,Number(t.value)||0));if(t.id==='v5-purpose')V5.purpose=t.value;if(t.id==='v5-return')V5.returnAt=t.value;if(t.id==='v5-weather-place')V5.weatherPlace=t.value});
document.addEventListener('submit',e=>{const id=vFormId(e.target);if(!id.startsWith('v5-'))return;e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(id==='v5-profile'){V5.profile={name:f.name,account:f.account,language:f.language||V5.profile.language};save('sy-v5-profile',V5.profile)}if(id==='v5-address-form'){V5.addresses.push({label:f.label,address:f.address});save('sy-v5-addresses',V5.addresses);$('#source-dialog').close()}if(id==='v5-place-form')V5.place=f.place;if(id==='v5-help'){const rows=stored('sy-v5-help');rows.push({...f,id:vId(),created:new Date().toISOString(),status:'本地草稿 · 未发布'});save('sy-v5-help',rows)}vRender()});
vRender();

function v5PlaceMap(){return `<svg viewBox="0 0 720 300" role="img" aria-label="罗湖公开站点全图"><rect width="720" height="300" fill="#f1f6fc"/>${D.stations.map(s=>{const x=40+(s.lon-114.1)/.08*620,y=260-(s.lat-22.52)/.07*210;const on=vAvailable().some(r=>r.risk_description.includes(s.name+'地铁站'));return `<g data-v5="place" data-value="${esc(s.name)}" tabindex="0" role="button" style="cursor:pointer"><title>${esc(s.name)}：${on?'关联长期隐患':'风险未知'}</title><circle cx="${x}" cy="${y}" r="8" fill="${on?'#d38a36':'#829bc1'}"/><text x="${x+12}" y="${y+4}" font-size="12" fill="#426082">${esc(s.name)}</text></g>`}).join('')}<text x="20" y="290" font-size="10" fill="#73859b">© OpenStreetMap contributors · 坐标示意，非完整底图</text></svg>`}

const v5MapBase=vMap,v5HazardBase=vHazards,v5CompareBase=vCompare;
vMap=function(scope='all'){return v5MapBase(scope)+v5End(scope==='comparison'?'路径比较':'路线位置图')};
vHazards=function(){return v5HazardBase()+v5End('关联隐患')};
vCompare=function(){return v5CompareBase()+v5End('方案比较')};
vRender();
